34: function ParamControl({
35:   spec,
36:   value,
37:   onChange,
38: }: {
39:   spec: ParamSpec;
40:   value: unknown;
41:   onChange: (name: string, value: unknown) => void;
42: }) {
43:   const label = spec.label ?? spec.name;
