1: /**
2:  * Param projection — the two halves of the "one declaration drives both" goal:
3:  *  - applyParams: user's chosen values → request-body fields (via wire.field).
4:  *  - buildParamsDoc: the param specs → a natural-language note injected into the
5:  *    tool description so the agent knows what a configured model accepts.
6:  * See docs/superpowers/specs/2026-06-15-unified-model-catalog-design.md §4/§6.
7:  */
8: import type { ParamSpec } from "./types.js";
9: 
10: /**
11:  * Project `values` onto a request-body fragment using each spec's wire.field
12:  * (falling back to the param name). A dotted field ("thinking.budget_tokens")
13:  * nests. Values with no matching spec, and specs the user didn't set, are
14:  * skipped.
15:  */
16: export function applyParams(
17:   values: Record<string, unknown>,
18:   params: ParamSpec[],
19: ): Record<string, unknown> {
20:   const body: Record<string, unknown> = {};
21:   for (const spec of params) {
22:     if (!(spec.name in values)) continue;
23:     const value = values[spec.name];
24:     if (value === undefined) continue;
25:     const field = spec.wire?.field ?? spec.name;
26:     setDeep(body, field, value);
27:   }
28:   return body;
29: }
30: 
31: /** Set a (possibly dotted) path on an object, creating intermediate objects. */
32: function setDeep(obj: Record<string, unknown>, path: string, value: unknown): void {
33:   const parts = path.split(".");
34:   let cur = obj;
35:   for (let i = 0; i < parts.length - 1; i++) {
36:     const key = parts[i]!;
37:     if (typeof cur[key] !== "object" || cur[key] === null) cur[key] = {};
38:     cur = cur[key] as Record<string, unknown>;
39:   }
40:   cur[parts[parts.length - 1]!] = value;
41: }
42: 
43: /**
44:  * Build a natural-language note describing the params a model accepts, for
45:  * injection into the tool description. Empty string when there are no params.
46:  */
47: export function buildParamsDoc(params: ParamSpec[] | undefined): string {
48:   if (!params || params.length === 0) return "";
49:   const lines = params.map((p) => {
50:     const opts = p.options && p.options.length > 0 ? ` (${p.options.join(" | ")})` : "";
51:     const doc = p.doc ? ` — ${p.doc}` : "";
52:     return `${p.name}${opts}${doc}`;
53:   });
54:   return lines.join("; ");
55: }

