117: /** Keep only values supported by the newly selected model, seeding its defaults. */
118: export function modelSelectionPatch(
119:   instance: ModelInstance,
120:   entry: CatalogEntry | undefined,
121:   model: string,
122: ): Pick<ModelInstance, "model" | "paramValues"> {
123:   const paramValues: Record<string, unknown> = {};
124:   for (const param of entry?.modelPresets?.find((preset) => preset.value === model)?.params ?? []) {
