129:         : param.control === "toggle"
130:           ? typeof value === "boolean"
131:           : param.control === "number"
132:             ? typeof value === "number" &&
133:               Number.isFinite(value) &&
134:               (param.min === undefined || value >= param.min) &&
135:               (param.max === undefined || value <= param.max)
136:             : typeof value === "string" && (param.max === undefined || value.length <= param.max);
137:     if (compatible) paramValues[param.name] = value;
138:     else if (param.default !== undefined) paramValues[param.name] = param.default;
139:   }
140:   return { model, paramValues };
141: }

